static मशीन_शब्द गतिमानस्मृतिराशी_संग्रह[8192];static unsigned वापरलेले_धारणक्षमता;
void जावाअपयश(void){const char पाठ्य[]="AOT runtime error\n";संचिका_डेटा_लिहा(2,पाठ्य,sizeof(पाठ्य)-1);प्रयोक्ता_आवाहन(6,1,0,0,0,0,0);for(;;){}}
void जावाराशीवरठेवा(मशीन_शब्द *स्टॅक_संग्रह,int *खोली_मूल्य,मशीन_शब्द मूल्य){if(*खोली_मूल्य<0||*खोली_मूल्य>=128)जावाअपयश();स्टॅक_संग्रह[(*खोली_मूल्य)++]=मूल्य;}
मशीन_शब्द जावा_पोस्ट_ऑफिस_प्रोटोकॉल_मूल्य(मशीन_शब्द *स्टॅक_संग्रह,int *खोली_मूल्य){if(*खोली_मूल्य<=0||*खोली_मूल्य>128)जावाअपयश();return स्टॅक_संग्रह[--*खोली_मूल्य];}
मशीन_शब्द जावाव्यूह(int आयटम_संख्या){if(आयटम_संख्या<0||(unsigned)आयटम_संख्या+1>8192-वापरलेले_धारणक्षमता)जावाअपयश();मशीन_शब्द*डेटा_स्थान=गतिमानस्मृतिराशी_संग्रह+वापरलेले_धारणक्षमता;वापरलेले_धारणक्षमता+=आयटम_संख्या+1;डेटा_स्थान[0]=आयटम_संख्या;return (मशीन_शब्द)डेटा_स्थान;}
मशीन_शब्द *जावाअनुक्रम(मशीन_शब्द ऑब्जेक्ट_संदर्भ,int आयटम_संख्या){मशीन_शब्द*डेटा_स्थान=(मशीन_शब्द*)ऑब्जेक्ट_संदर्भ;if(!डेटा_स्थान||आयटम_संख्या<0||(मशीन_शब्द)आयटम_संख्या>=डेटा_स्थान[0])जावाअपयश();return डेटा_स्थान+आयटम_संख्या+1;}
int जावालांबी(मशीन_शब्द ऑब्जेक्ट_संदर्भ){if(!ऑब्जेक्ट_संदर्भ)जावाअपयश();return *(मशीन_शब्द*)ऑब्जेक्ट_संदर्भ;}
int जावाभागाकार(int आडवे_समन्वयीत,int उभे_समन्वयीत,int बाकी_मूल्य){if(!उभे_समन्वयीत)जावाअपयश();if(आडवे_समन्वयीत==(-2147483647-1)&&उभे_समन्वयीत==-1)return बाकी_मूल्य?0:आडवे_समन्वयीत;return बाकी_मूल्य?आडवे_समन्वयीत%उभे_समन्वयीत:आडवे_समन्वयीत/उभे_समन्वयीत;}
static unsigned लांबी_मूल्य(const char*स्ट्रींग_डेटा){unsigned आयटम_संख्या=0;if(!स्ट्रींग_डेटा)जावाअपयश();while(स्ट्रींग_डेटा[आयटम_संख्या])आयटम_संख्या++;return आयटम_संख्या;}
void जावाछापा(मशीन_शब्द डेटा_स्थान,int संख्यात्मक_मूल्य,int नवीओळ){
    if(संख्यात्मक_मूल्य){char दुसरे_मूल्य[16];unsigned आयटम_संख्या=0;int मूल्य=(int)डेटा_स्थान;unsigned चिन्हरहित_मूल्य=मूल्य<0?0-(unsigned)मूल्य:मूल्य;do{दुसरे_मूल्य[आयटम_संख्या++]='0'+चिन्हरहित_मूल्य%10;चिन्हरहित_मूल्य/=10;}while(चिन्हरहित_मूल्य);if(मूल्य<0)दुसरे_मूल्य[आयटम_संख्या++]='-';while(आयटम_संख्या)संचिका_डेटा_लिहा(1,दुसरे_मूल्य+--आयटम_संख्या,1);}
    else{const char*स्ट्रींग_डेटा=डेटा_स्थान?(const char*)डेटा_स्थान:"null";संचिका_डेटा_लिहा(1,स्ट्रींग_डेटा,लांबी_मूल्य(स्ट्रींग_डेटा));}if(नवीओळ)संचिका_डेटा_लिहा(1,"\n",1);
}
मशीन_शब्द जावासंचिकालेखन(मशीन_शब्द मार्ग,मशीन_शब्द मूल्य){const char*स्ट्रींग_डेटा=(const char*)मूल्य;unsigned आयटम_संख्या=लांबी_मूल्य(स्ट्रींग_डेटा);int संचिका_हाताळा=संचिका_उघडा((const char*)मार्ग,केवळ_मूल्य_लिहा|जर_अनुपस्थित_तयार_करा|छाटूनरिकामेकरा_सामुग्री,0600);if(संचिका_हाताळा<0)जावाअपयश();int परतलेले_मूल्य=संचिका_डेटा_लिहा(संचिका_हाताळा,स्ट्रींग_डेटा,आयटम_संख्या);संचिका_मिटवा(संचिका_हाताळा);if(परतलेले_मूल्य!=(int)आयटम_संख्या)जावाअपयश();return 0;}
मशीन_शब्द जावासंचिकावाचन(मशीन_शब्द मार्ग){int संचिका_हाताळा=संचिका_उघडा((const char*)मार्ग,केवळ_मूल्य_वाचा,0);if(संचिका_हाताळा<0)जावाअपयश();int आयटम_संख्या=संचिका_आकारा(संचिका_हाताळा);if(आयटम_संख्या<0||आयटम_संख्या>16384||(unsigned)(आयटम_संख्या+8)/8>8192-वापरलेले_धारणक्षमता)जावाअपयश();char*डेटा_स्थान=(char*)(गतिमानस्मृतिराशी_संग्रह+वापरलेले_धारणक्षमता);वापरलेले_धारणक्षमता+=(आयटम_संख्या+8)/8;int परतलेले_मूल्य=संचिका_डेटा_वाचा(संचिका_हाताळा,डेटा_स्थान,आयटम_संख्या);संचिका_मिटवा(संचिका_हाताळा);if(परतलेले_मूल्य!=आयटम_संख्या)जावाअपयश();डेटा_स्थान[आयटम_संख्या]=0;return (मशीन_शब्द)डेटा_स्थान;}
